// Extract start and end times
for (int i = 0; i < n; i++) {
  starts[i] = intervals[i].start;
  ends[i] = intervals[i].end;
}

// Sort start times and end times separately
sort(starts, starts + n);
sort(ends, ends + n);

int overlaps = 0;
int max_overlaps = 0;
int i = 0;
int j = 0;

while (i < n) {
  if (starts[i] < ends[j]) {
    overlaps++;
    i++;
    if (overlaps > max_overlaps) max_overlaps = overlaps;
  } else {
    overlaps--;
    j++;
  }
}
```

Note: use `starts[i] <= ends[j]` if touching counts as overlap.

```c
// Sort intervals by start time

// Minimum-oriented priority queue gives access to earliest-ending interval
min_heap<int> ends;

for (int i = 0; i < n; i++) {
  // Release earliest-ending interval if it ends before current interval
  if (!ends.empty() && ends.peek_min() <= intervals[i].start) {
    ends.pop_min();
  }

  // Add the end time of this interval to the queue
  ends.push(intervals[i].end);
}

// Number of rooms needed is nondecreasing; priority queue
// size at end of loop is the max number of rooms.
return ends.size();
```

