// sort intervals by start time

// Minimum-oriented priority queue ordered by end time
min_heap<pair<int, int>> rooms;  // (end, id)
int next_id = 1;

for (int i = 0; i < n; i++) {
  int id;

  if (!rooms.empty() && rooms.peek_min().end <= intervals[i].start) {
    id = rooms.pop_min().id;  // store id for reuse
  } else {
    id = next_id++;           // allocate new room
  }

  rooms.push({intervals[i].end, id});
}

return rooms.size();
```
